package com.obysoft.faithOS.controller;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import com.obysoft.faithOS.dto.*;import com.obysoft.faithOS.service.MemberMessageService;
@RestController @RequestMapping("/api/member-messages")public class MemberMessageController{private final MemberMessageService service;public MemberMessageController(MemberMessageService s){service=s;}@GetMapping("/contacts")public List<MessageContactResponse> contacts(){return service.contacts();}@GetMapping("/with/{id}")public List<MemberMessageResponse> conversation(@PathVariable Long id){return service.conversation(id);}@PostMapping(value="/to/{id}",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)public ResponseEntity<MemberMessageResponse> send(@PathVariable Long id,@RequestParam(required=false)String message,@RequestParam(required=false)MultipartFile file){return ResponseEntity.status(201).body(service.send(id,message,file));}@GetMapping("/{id}/attachment")public ResponseEntity<byte[]> attachment(@PathVariable Long id){var a=service.attachment(id);return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).header("X-Content-Type-Options","nosniff").header("Content-Security-Policy","default-src 'none'").header(HttpHeaders.CACHE_CONTROL,"no-store").header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(a.name()).build().toString()).body(a.data());}}
